      es: ["Población: aprox. 8.000", "Distancia a Mogadiscio: 120 km", "Cultivo principal: sorgo", "Número de mezquitas: 1", "Escuelas: 1", "Clima: semiárido"],
      pt: ["População: aprox. 8.000", "Distância de Mogadíscio: 120 km", "Cultura principal: sorgo", "Número de mesquitas: 1", "Escolas: 1", "Clima: semiárido"],
